const COL = {NAAM:0,LINK:1,MAPS:2,ADRES:3,ELS:4,SERGE:5,AVG:6,CATEGORY:7,STATUS:8,BUDGET:9,SEASON:10,OPMERKINGEN:11,RESERVATION:12,LAT:13,LNG:14,PINNED:15};
